function validate([nums, queries, x]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each value of nums is an integer from 1 to 10^4.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 values.';
  if (queries.some(q => !Number.isInteger(q) || q < 1 || q > 100000)) return 'Each query is an integer from 1 to 10^5.';
  if (!Number.isInteger(x) || x < 1 || x > 10000) return 'x is an integer from 1 to 10^4.';
  return null;
}

