function occurrencesOfElement(nums, queries, x) {
  // positions.get(value) lists the indices holding value, in increasing order.
  const positions = new Map();
  for (let i = 0; i < nums.length; i++) {
    if (!positions.has(nums[i])) {
      positions.set(nums[i], []);
    }
    positions.get(nums[i]).push(i);
  }
  const occurrences = positions.get(x) ?? [];
  const answer = [];
  for (const nth of queries) {
    if (nth <= occurrences.length) {
      answer.push(occurrences[nth - 1]);
    } else {
      answer.push(-1);
    }
  }
  return answer;
}

