function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 10);
  // Pick how common x is: absent (small inputs only), rare, frequent or almost everywhere.
  const share = large ? [0.05, 0.4, 0.95][int(0, 2)] : [0, 0.3, 0.6, 0.95][int(0, 3)];
  const top = large || rand() < 0.3 ? 10000 : 4;
  const x = int(1, top);
  const other = () => {
    const v = int(1, top);
    return v !== x ? v : v === top ? v - 1 : v + 1;
  };
  const nums = Array.from({ length: n }, () => (rand() < share ? x : other()));
  const count = nums.filter(v => v === x).length;
  const queries = Array.from({ length: large ? 2000 : int(1, 6) }, () => {
    const r = rand();
    if (r < 0.1) return int(1, 100000);
    if (r < 0.2) return 1;
    return int(1, count + 1);
  });
  return [nums, queries, x];
}
